CREATE TABLE "public"."book_reviews" (
  "id"           bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "book_id"      text                     NOT NULL,
  "visitor_id"   text,
  "visitor_name" text                     NOT NULL,
  "rating"       integer,
  "comment"      text                     NOT NULL,
  "created_at"   timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  CONSTRAINT "book_reviews_pkey" PRIMARY KEY (id),
  CONSTRAINT "book_reviews_rating_check" CHECK (((rating >= 1) AND (rating <= 5)))
);

CREATE INDEX IF NOT EXISTS book_reviews_book_id_rating_idx
  ON public.book_reviews (book_id) INCLUDE (rating);

CREATE TRIGGER maintain_book_rating_aggregates
  AFTER INSERT OR UPDATE OF book_id, rating OR DELETE ON public.book_reviews
  FOR EACH ROW
  EXECUTE FUNCTION public.maintain_book_rating_aggregates();

ALTER TABLE "public"."book_reviews"
  ENABLE ROW LEVEL SECURITY;

CREATE POLICY "read public reviews" ON "public"."book_reviews"
  FOR SELECT
  TO "anon", "authenticated"
  USING (true);

CREATE POLICY "visitors manage own reviews" ON "public"."book_reviews"
  FOR ALL
  TO "authenticated"
  USING ((EXISTS ( SELECT 1
   FROM public.visitors visitor
  WHERE ((visitor.auth_user_id = auth.uid()) AND visitor.otp_verified AND visitor.is_active))))
  WITH CHECK ((EXISTS ( SELECT 1
   FROM public.visitors visitor
  WHERE ((visitor.auth_user_id = auth.uid()) AND visitor.otp_verified AND visitor.is_active))));

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."book_reviews" TO "postgres", "service_role";

REVOKE ALL ON TABLE "public"."book_reviews" FROM "authenticated";

GRANT DELETE, INSERT, SELECT, UPDATE ON TABLE "public"."book_reviews" TO "authenticated";
